#!/bin/bash
# Verifier for a skill-eval task (generated by harbor-bench).
#
# Runs in a SEPARATE verifier container that never sees the agent's injected
# skills, workspace, or agent logs. Harbor transfers only the task-level
# `artifacts` (here: /workspace + /logs/agent/copilot-cli.jsonl +
# /logs/agent/trajectory.json) re-materialized at their original paths, plus
# /logs/artifacts/; /logs/verifier/ is mounted for the reward.
set -uo pipefail

# --- F1: skill load + invoke proof (agent trajectory under /logs/agent) ----------
# Enforced unless SKILL_EVAL_ENFORCE_SKILL_USE=false (e.g. without-skill jobs).
SKILL_OK=1
TRANSCRIPT=""
if [ -d /logs/agent ]; then
  TRANSCRIPT=$(find /logs/agent -type f -name '*.jsonl' 2>/dev/null | head -n 1)
fi
if [ "${SKILL_EVAL_ENFORCE_SKILL_USE:-true}" = "true" ]; then
  SKILL_NAME="${SKILL_EVAL_SKILL_NAME:-figma-to-code}"
  if [ -n "$TRANSCRIPT" ]; then
    # load: skill context injected into the user turn
    if ! grep -q '<skill-context' "$TRANSCRIPT" 2>/dev/null; then
      SKILL_OK=0
    fi
    # invoke: at least one tool call to the `skill` tool
    if ! grep -q '"name" *: *"skill"' "$TRANSCRIPT" 2>/dev/null; then
      SKILL_OK=0
    fi
  else
    SKILL_OK=0
  fi
fi

if [ "$SKILL_OK" -eq 0 ]; then
  echo 0 > /logs/verifier/reward.txt
  echo "skill_use_ok=$SKILL_OK" > /logs/verifier/reason.txt
  exit 0
fi

# --- LLM judge (RewardKit quality.toml) ---------------------------------------
JUDGE_TOKEN="${OPENAI_API_KEY:-${COPILOT_GITHUB_TOKEN:-${GH_TOKEN:-${GITHUB_TOKEN:-}}}}"
if [ -n "$JUDGE_TOKEN" ]; then
  export PATH="$HOME/.local/bin:$PATH"
  # uv is baked into the verifier image (verifier-Dockerfile); keep a fallback
  # install so the same test.sh also works in shared-verifier mode.
  if ! command -v uv >/dev/null 2>&1; then
    curl -LsSf https://astral.sh/uv/install.sh | sh
    export PATH="$HOME/.local/bin:$PATH"
  fi
  # Recursive workspace packet: RewardKit [judge].files does not recurse
  # directories, so concat the produced files (transferred artifact /workspace)
  # into one markdown the judge reads; the ATIF trajectory (/logs/agent) lets
  # the judge see tool calls for process-based criteria.
  # Workspace packet for the judge. Delta vs. the generated template: the
  # template concatenates every file in /workspace, which for a real checkout
  # (or a vendored dependency tree) is tens of megabytes and unusable as a
  # judge input. Here the packet is text-only, ordered newest-first so the
  # files the agent touched survive the cap, and bounded.
  mkdir -p /logs/artifacts
  python3 - <<'PACKET_EOF' || true
import os
from pathlib import Path

ROOT = Path("/workspace")
OUT = Path("/logs/artifacts/workspace-packet.md")
SKIP_DIRS = {
    ".git", ".agents", ".harbor", ".mise", ".nx", ".pnpm-store",
    "node_modules", "vendor", "dist", "coverage", "build",
}
SKIP_SUFFIX = {
    ".png", ".jpg", ".jpeg", ".gif", ".webp", ".ico", ".bmp", ".pdf",
    ".zip", ".gz", ".br", ".tar", ".woff", ".woff2", ".ttf", ".otf",
    ".mp4", ".webm", ".mov", ".wasm", ".node",
}
MAX_FILE = 48 * 1024
MAX_TOTAL = 400 * 1024
MAX_LISTED = 300

def readable(path):
    try:
        data = path.read_bytes()
        mtime = path.stat().st_mtime
    except OSError:
        return None
    if b"\x00" in data[:8192] or len(data) > MAX_FILE:
        return None
    return data, mtime

found = []
for base, dirs, files in os.walk(ROOT):
    dirs[:] = sorted(d for d in dirs if d not in SKIP_DIRS)
    for name in sorted(files):
        path = Path(base) / name
        rel = path.relative_to(ROOT).as_posix()
        if path.suffix.lower() in SKIP_SUFFIX:
            found.append((rel, None, 0.0))
            continue
        got = readable(path)
        found.append((rel, got[0] if got else None, got[1] if got else 0.0))

# Newest first: the agent's own writes are the newest files in the image.
found.sort(key=lambda item: (-item[2], item[0]))

chunks = ["# Workspace packet\n\nFiles are ordered by modification time, newest"
          " first; a size cap may omit older ones (listed at the end).\n"]
total = 0
hidden = []
for rel, data, _ in found:
    if data is None:
        hidden.append(rel)
        continue
    chunk = f"\n--- /workspace/{rel} ---\n\n" + data.decode("utf-8", "replace")
    if total + len(chunk) > MAX_TOTAL:
        hidden.append(rel)
        continue
    chunks.append(chunk)
    total += len(chunk)
if hidden:
    chunks.append(
        f"\n--- not shown: {len(hidden)} file(s) (binary, oversized or over the"
        " packet cap) ---\n\n"
        + "\n".join(f"/workspace/{rel}" for rel in sorted(hidden)[:MAX_LISTED])
    )
OUT.write_text("".join(chunks), encoding="utf-8")
PACKET_EOF

  # Record per-call judge token usage: harbor-rewardkit 0.2.0 discards the LLM
  # response usage, so a `sitecustomize` shim patches `litellm.acompletion` to
  # tee each response's usage into /logs/verifier/usage.jsonl (aggregated by
  # `harbor-bench report`). The patch is inert if litellm is unavailable.
  cat > /tmp/sitecustomize.py << 'PYEOF'
import json, os
USAGE_FILE = os.environ.get("JUDGE_USAGE_FILE", "/logs/verifier/usage.jsonl")
try:
    import litellm
    _original = litellm.acompletion
    async def _patched(*args, **kwargs):
        resp = await _original(*args, **kwargs)
        try:
            usage = getattr(resp, "usage", None)
            if hasattr(usage, "model_dump"):
                usage = usage.model_dump()
            elif usage is not None and not isinstance(usage, dict):
                usage = dict(usage)
            with open(USAGE_FILE, "a", encoding="utf-8") as fh:
                fh.write(json.dumps({"usage": usage or {}}) + "\n")
        except Exception:
            pass
        return resp
    litellm.acompletion = _patched
except Exception:
    pass
PYEOF
  export PYTHONPATH="/tmp:${PYTHONPATH:-}"

  # litellm 1.108 (pulled by harbor-rewardkit 0.2.0) imports `mcp` while routing
  # openai/* calls to the Responses API; rewardkit does not declare it, so the
  # judge dies with ModuleNotFoundError without this extra.
  uvx --with mcp --from harbor-rewardkit==0.2.0 rewardkit /tests \
    --workspace /workspace \
    --output /logs/verifier/reward.json \
    || true

  # Record the scoring gate (quality.toml [scoring]) next to the reward.
  # RewardKit 0.2.0 does not persist its scoring config, and Harbor downloads
  # the whole /logs/verifier directory: this file is how a comparison
  # report on a copied run directory shows a score against its gate. Absent
  # when the task declares no scoring block.
  python3 - <<'PYEOF' || true
import json
import tomllib
with open("/tests/quality.toml", "rb") as fh:
    scoring = (tomllib.load(fh) or {}).get("scoring") or {}
if scoring:
    with open("/logs/verifier/scoring.json", "w", encoding="utf-8") as fh:
        json.dump(scoring, fh, indent=2)
PYEOF

  # Harbor reads reward.json by default and falls back to reward.txt. Only
  # write the text fallback when RewardKit produced no usable reward.json.
  if [ ! -s /logs/verifier/reward.json ]; then
    rm -f /logs/verifier/reward.json
    echo 0 > /logs/verifier/reward.txt
  fi
else
  echo 1 > /logs/verifier/reward.txt
fi
